    fwrite(body, 1, show, stdout);
    if (show < n) printf("\n[... %zu more bytes; use --full]", n - show);
    fputs("\n\n", stdout);
  }
  if (rc != SQLITE_DONE) die("%s", sqlite3_errmsg(db));
  sqlite3_finalize(q);
  sqlite3_close(db);
  if (!found) die("no turn #%d", nums[0]);
  return 0;
}

